// ============================================================================
// Nexo Studio Update v3 — Plugin de desarrollo para Figma
// ----------------------------------------------------------------------------
// Automatización completa del rebrand Digital Creators → Nexo Studio.
// Esta versión hace TODO lo que antes era manual: imagotipo en headers,
// isologo en hero, isotipo en footers, reestructuración de team cards,
// service cards 2×2 con íconos SVG, paleta completa en Style Guide,
// eliminación del bloque Box Model, nav uppercased + underline activo.
//
// Idempotente: corré las veces que quieras, no duplica nada.
// Si algo no te convence, Ctrl+Z deshace todo el batch.
// ============================================================================

(async () => {
  // ──────────────────────────────────────────────────────────────────────────
  // HELPERS
  // ──────────────────────────────────────────────────────────────────────────
  const log = function () { console.log.apply(console, ["[NEXO]"].concat([].slice.call(arguments))); };

  function rgb(r, g, b) { return { r: r / 255, g: g / 255, b: b / 255 }; }

  function isAlive(node) {
    if (!node) return false;
    try {
      if (node.removed === true) return false;
      var _ = node.name;
      return true;
    } catch (e) { return false; }
  }

  function base64ToBytes(b64) {
    var binary = atob(b64);
    var len = binary.length;
    var bytes = new Uint8Array(len);
    for (var i = 0; i < len; i++) bytes[i] = binary.charCodeAt(i);
    return bytes;
  }

  async function loadFontsForNode(textNode) {
    var fn = textNode.fontName;
    if (fn !== figma.mixed) {
      try { await figma.loadFontAsync(fn); } catch (e) {}
      return;
    }
    var len = textNode.characters.length;
    var fonts = {};
    for (var i = 0; i < len; i++) {
      var f = textNode.getRangeFontName(i, i + 1);
      if (f !== figma.mixed) fonts[JSON.stringify(f)] = f;
    }
    for (var k in fonts) {
      try { await figma.loadFontAsync(fonts[k]); } catch (e) {}
    }
  }

  async function setText(textNode, newText) {
    await loadFontsForNode(textNode);
    textNode.characters = newText;
  }

  async function safeRemove(node) {
    try { if (isAlive(node)) node.remove(); } catch (e) {}
  }

  // ──────────────────────────────────────────────────────────────────────────
  // COLOR CONSTANTS (paleta Nexo Studio)
  // ──────────────────────────────────────────────────────────────────────────
  var COLORS = {
    primary:      rgb(0, 51, 102),    // #003366
    accent:       rgb(255, 102, 0),   // #ff6600
    accentHover:  rgb(204, 82, 0),    // #cc5200
    bgWhite:      rgb(255, 255, 255), // #ffffff
    bgCard:       rgb(248, 248, 248), // #f8f8f8
    bgIcon:       rgb(240, 244, 250), // #f0f4fa
    bgIconHover:  rgb(255, 244, 238), // #fff4ee
    navMobile:    rgb(0, 34, 85),     // #002255
    textMain:     rgb(26, 26, 26),    // #1a1a1a
    textPara:     rgb(68, 68, 68),    // #444444
    textSec:      rgb(85, 85, 85),    // #555555
    textMuted:    rgb(136, 136, 136), // #888888
    borderLight:  rgb(232, 232, 232), // #e8e8e8
    borderCard:   rgb(224, 224, 224), // #e0e0e0
    borderInput:  rgb(204, 204, 204), // #cccccc
    bgInput:      rgb(250, 250, 250), // #fafafa
  };

  // ──────────────────────────────────────────────────────────────────────────
  // IMAGES (base64 inline — sustituidas por Python al generar este archivo)
  // ──────────────────────────────────────────────────────────────────────────
  var IMAGOTIPO_B64 = "";
  var ISOLOGO_B64   = "";
  var ISOTIPO_B64   = "";

  // ──────────────────────────────────────────────────────────────────────────
  // STATS
  // ──────────────────────────────────────────────────────────────────────────
  var stats = {
    framesRenamed: 0, textsReplaced: 0, serviceCardsUpdated: 0,
    serviceCardsDeleted: 0, bordersApplied: 0, imagesInserted: 0,
    teamCardsRestructured: 0, serviceCardsRestructured: 0, iconsAdded: 0,
    swatchesAdded: 0, boxModelRemoved: 0, navsUpdated: 0,
    errors: [],
  };

  try {
    log("════════════════════════════════════════");
    log("Nexo Studio Update v3 — iniciando");
    log("════════════════════════════════════════");
    figma.notify("Nexo Studio v3 corriendo…", { timeout: 3000 });

    // ────────────────────────────────────────────────────────────────────────
    // LOAD FONTS
    // ────────────────────────────────────────────────────────────────────────
    log("Pre-cargando fuentes…");
    var fontVariants = [
      { family: "Montserrat", style: "Regular" },
      { family: "Montserrat", style: "Medium" },
      { family: "Montserrat", style: "SemiBold" },
      { family: "Montserrat", style: "Bold" },
      { family: "Open Sans", style: "Regular" },
      { family: "Open Sans", style: "SemiBold" },
    ];
    for (var fi = 0; fi < fontVariants.length; fi++) {
      try { await figma.loadFontAsync(fontVariants[fi]); } catch (e) {}
    }

    // ────────────────────────────────────────────────────────────────────────
    // LOAD IMAGES
    // ────────────────────────────────────────────────────────────────────────
    log("Importando imágenes (imagotipo, isologo, isotipo)…");
    var imagotipoImg = null, isologoImg = null, isotipoImg = null;
    try { imagotipoImg = figma.createImage(base64ToBytes(IMAGOTIPO_B64)); } catch (e) { stats.errors.push("imagotipo: " + e.message); }
    try { isologoImg = figma.createImage(base64ToBytes(ISOLOGO_B64)); } catch (e) { stats.errors.push("isologo: " + e.message); }
    try { isotipoImg = figma.createImage(base64ToBytes(ISOTIPO_B64)); } catch (e) { stats.errors.push("isotipo: " + e.message); }
    if (imagotipoImg && isologoImg && isotipoImg) log("   ✓ 3 imágenes importadas");

    // ────────────────────────────────────────────────────────────────────────
    // COLLECT ALL NODES
    // ────────────────────────────────────────────────────────────────────────
    var allNodes = [];
    for (var p = 0; p < figma.root.children.length; p++) {
      var page = figma.root.children[p];
      allNodes = allNodes.concat(page.findAll(function () { return true; }));
    }
    function aliveText(n) { return n.type === "TEXT" && isAlive(n); }
    function aliveFrame(n) { return n.type === "FRAME" && isAlive(n); }
    log("Nodos encontrados: " + allNodes.length);

    // ════════════════════════════════════════════════════════════════════════
    // STEP 1 · Renombrar frames principales
    // ════════════════════════════════════════════════════════════════════════
    log("");
    log("1) Renombrando frames…");
    var frameRenames = {
      "DC – Inicio":    "Nexo Studio – Inicio",
      "DC – Servicios": "Nexo Studio – Servicios",
      "DC – Proyectos": "Nexo Studio – Proyectos",
      "DC – Contacto":  "Nexo Studio – Contacto",
      "Style Guide":    "Nexo Studio – Style Guide",
    };
    for (var i = 0; i < allNodes.length; i++) {
      var n = allNodes[i];
      if (!isAlive(n)) continue;
      if (n.type === "FRAME" && frameRenames[n.name]) {
        log("   ✓ " + n.name + " → " + frameRenames[n.name]);
        n.name = frameRenames[n.name];
        stats.framesRenamed++;
      }
    }

    // ════════════════════════════════════════════════════════════════════════
    // STEP 2 · Reemplazos de texto
    // ════════════════════════════════════════════════════════════════════════
    log("");
    log("2) Reemplazando textos…");
    var textReplacements = [
      ["Digital Creators — Style Guide", "Nexo Studio — Style Guide"],
      ["Digital Creators · DDW1C26", "Nexo Studio · DDW1C26"],
      ["Bienvenidos a Digital Creators", "Bienvenidos a Nexo Studio"],
      ["En Digital Creators inyectamos", "En Nexo Studio inyectamos"],
      ["En Digital Creators, transformamos", "En Nexo Studio, transformamos"],
      ["Conocé a los 5 integrantes de Digital Creators", "Conocé a los 5 integrantes de Nexo Studio"],
      ["© 2026 Digital Creators. Todos los derechos reservados.", "© 2026 Nexo Studio. Todos los derechos reservados."],
      ["hola@digitalcreators.com", "hola@nexostudio.com"],
      ["digitalcreators.com", "nexostudio.com"],
      ["font-size: 32px | line-height: 44px", "font-size: 36px | line-height: 48px"],
      ["font-size: 24px | line-height: 32px", "font-size: 26px | line-height: 36px"],
      ["font-size: 20px | line-height: 28px", "font-size: 18px | line-height: 28px"],
      ["font-weight: 600 (SemiBold)", "font-weight: 700 (Bold)"],
      ["font-weight: 500 (Medium)", "font-weight: 700 (Bold)"],
      ["Digital Creators", "Nexo Studio"],
    ];
    for (var t = 0; t < allNodes.length; t++) {
      var tn = allNodes[t];
      if (!aliveText(tn)) continue;
      var original;
      try { original = tn.characters; } catch (e) { continue; }
      var updated = original;
      for (var r = 0; r < textReplacements.length; r++) {
        var p2 = textReplacements[r][0], rr = textReplacements[r][1];
        if (updated.indexOf(p2) !== -1) updated = updated.split(p2).join(rr);
      }
      if (updated !== original) {
        try {
          await setText(tn, updated);
          stats.textsReplaced++;
        } catch (e) { stats.errors.push("text: " + e.message); }
      }
    }
    log("   ✓ " + stats.textsReplaced + " textos modificados");

    // ════════════════════════════════════════════════════════════════════════
    // STEP 3 · Service cards (renombrar + actualizar descripciones + borrar 5ta)
    // ════════════════════════════════════════════════════════════════════════
    log("");
    log("3) Actualizando service cards…");
    var serviceUpdates = [
      { oldName: "Card - Diseño UX / UI",        newName: "Card - Diseño UX/UI",
        title: "Diseño UX/UI",
        desc:  "Diseñamos experiencias intuitivas y agradables, centradas en el usuario y orientadas a resultados." },
      { oldName: "Card - Desarrollo Web",         newName: "Card - Desarrollo Front-end",
        title: "Desarrollo Front-end",
        desc:  "Construimos sitios y aplicaciones web modernas, accesibles y optimizadas para todos los dispositivos." },
      { oldName: "Card - Branding",               newName: "Card - User Research",
        title: "User Research",
        desc:  "Investigamos a fondo para entender a tu audiencia mediante encuestas, entrevistas y testing de usabilidad." },
      { oldName: "Card - Estrategia Digital",     newName: "Card - Marketing Digital",
        title: "Marketing Digital",
        desc:  "Diseñamos estrategias de comunicación y contenido para amplificar tu presencia online y atraer a tu audiencia." },
    ];
    function findFrameByName(name) {
      for (var i = 0; i < allNodes.length; i++) {
        var nn = allNodes[i];
        if (aliveFrame(nn) && nn.name === name) return nn;
      }
      return null;
    }
    for (var su = 0; su < serviceUpdates.length; su++) {
      var upd = serviceUpdates[su];
      var card = findFrameByName(upd.oldName);
      if (!card) continue;
      var cardTexts = card.findAll(function (x) { return x.type === "TEXT"; });
      if (cardTexts.length < 2) continue;
      var sorted = cardTexts.slice().sort(function (a, b) { return a.characters.length - b.characters.length; });
      try {
        await setText(sorted[0], upd.title);
        await setText(sorted[sorted.length - 1], upd.desc);
        card.name = upd.newName;
        stats.serviceCardsUpdated++;
      } catch (e) { stats.errors.push("svc: " + e.message); }
    }
    var consul = findFrameByName("Card - Consultoría Tecnológica");
    if (consul) { await safeRemove(consul); stats.serviceCardsDeleted++; log("   ✓ Consultoría Tecnológica eliminada"); }
    log("   ✓ " + stats.serviceCardsUpdated + " cards renombradas");

    // ════════════════════════════════════════════════════════════════════════
    // STEP 4 · Bordes naranja Header/Footer
    // ════════════════════════════════════════════════════════════════════════
    log("");
    log("4) Bordes naranja Header/Footer…");
    function applyEdgeStroke(frame, side) {
      try {
        frame.strokes = [{ type: "SOLID", color: COLORS.accent }];
        frame.strokeAlign = "INSIDE";
        frame.strokeWeight = 3;
        try {
          frame.strokeTopWeight    = side === "top"    ? 3 : 0;
          frame.strokeBottomWeight = side === "bottom" ? 3 : 0;
          frame.strokeLeftWeight   = 0;
          frame.strokeRightWeight  = 0;
        } catch (e) {}
      } catch (e) { stats.errors.push("stroke: " + e.message); }
    }
    for (var bf = 0; bf < allNodes.length; bf++) {
      var fr = allNodes[bf];
      if (!aliveFrame(fr)) continue;
      var nm;
      try { nm = fr.name; } catch (e) { continue; }
      if (nm === "Header") { applyEdgeStroke(fr, "bottom"); stats.bordersApplied++; }
      else if (nm === "Footer") { applyEdgeStroke(fr, "top"); stats.bordersApplied++; }
    }
    log("   ✓ " + stats.bordersApplied + " bordes aplicados");

    // ════════════════════════════════════════════════════════════════════════
    // STEP 5 · Imagotipo en Headers
    // ════════════════════════════════════════════════════════════════════════
    log("");
    log("5) Imagotipo en Headers…");
    if (imagotipoImg) {
      for (var h = 0; h < allNodes.length; h++) {
        var header = allNodes[h];
        if (!aliveFrame(header) || header.name !== "Header") continue;
        try {
          var existing = header.findOne(function (x) { return x.name === "Imagotipo logo"; });
          if (existing) continue;
          var brandText = header.findOne(function (x) {
            return x.type === "TEXT" && (x.characters === "Nexo Studio" || x.characters === "Digital Creators");
          });
          var imgH = 40, imgW = 160;
          var rect = figma.createRectangle();
          rect.name = "Imagotipo logo";
          rect.resize(imgW, imgH);
          rect.x = brandText ? brandText.x : 40;
          rect.y = Math.round((header.height - imgH) / 2);
          rect.fills = [{ type: "IMAGE", imageHash: imagotipoImg.hash, scaleMode: "FIT" }];
          header.appendChild(rect);
          if (brandText) { brandText.visible = false; brandText.name = "(hidden) Brand text"; }
          stats.imagesInserted++;
        } catch (e) { stats.errors.push("imagotipo: " + e.message); }
      }
    }

    // ════════════════════════════════════════════════════════════════════════
    // STEP 6 · Isologo en Hero del Inicio
    // ════════════════════════════════════════════════════════════════════════
    log("");
    log("6) Isologo en Hero…");
    if (isologoImg) {
      var inicioFrame = findFrameByName("Nexo Studio – Inicio") || findFrameByName("DC – Inicio");
      if (inicioFrame) {
        try {
          var existing2 = inicioFrame.findOne(function (x) { return x.name === "Isologo hero"; });
          if (!existing2) {
            var mainFrame = inicioFrame.findOne(function (x) { return x.type === "FRAME" && x.name === "Main"; });
            var hostFrame = mainFrame || inicioFrame;
            var heroH1 = hostFrame.findOne(function (x) {
              return x.type === "TEXT" && x.characters && x.characters.indexOf("Bienvenidos") !== -1;
            });
            var iso = figma.createRectangle();
            iso.name = "Isologo hero";
            iso.resize(80, 80);
            iso.x = heroH1 ? heroH1.x : 40;
            iso.y = heroH1 ? Math.max(0, heroH1.y - 20) : 30;
            iso.fills = [{ type: "IMAGE", imageHash: isologoImg.hash, scaleMode: "FIT" }];
            hostFrame.appendChild(iso);
            if (heroH1) {
              heroH1.x = heroH1.x + 100;
              heroH1.y = heroH1.y + 20;
            }
            stats.imagesInserted++;
            log("   ✓ Isologo insertado");
          }
        } catch (e) { stats.errors.push("isologo: " + e.message); }
      }
    }

    // ════════════════════════════════════════════════════════════════════════
    // STEP 7 · Isotipo en Footers
    // ════════════════════════════════════════════════════════════════════════
    log("");
    log("7) Isotipo en Footers…");
    if (isotipoImg) {
      for (var ff = 0; ff < allNodes.length; ff++) {
        var footer = allNodes[ff];
        if (!aliveFrame(footer) || footer.name !== "Footer") continue;
        try {
          var existing3 = footer.findOne(function (x) { return x.name === "Isotipo footer"; });
          if (existing3) continue;
          try { footer.resize(footer.width, 80); } catch (e) {}
          var copyright = footer.findOne(function (x) {
            return x.type === "TEXT" && x.characters && x.characters.indexOf("©") !== -1;
          });
          var iso2 = figma.createRectangle();
          iso2.name = "Isotipo footer";
          iso2.resize(32, 32);
          iso2.x = Math.round((footer.width - 32) / 2);
          iso2.y = 12;
          iso2.fills = [{ type: "IMAGE", imageHash: isotipoImg.hash, scaleMode: "FIT" }];
          footer.appendChild(iso2);
          if (copyright) {
            copyright.y = 52;
            try {
              copyright.x = Math.round((footer.width - copyright.width) / 2);
            } catch (e) {}
          }
          stats.imagesInserted++;
        } catch (e) { stats.errors.push("isotipo footer: " + e.message); }
      }
    }

    // ════════════════════════════════════════════════════════════════════════
    // STEP 8 · Reestructurar team cards (foto rectangular arriba)
    // ════════════════════════════════════════════════════════════════════════
    log("");
    log("8) Reestructurando team cards…");
    var portfolioSection = null;
    for (var ps = 0; ps < allNodes.length; ps++) {
      var nn2 = allNodes[ps];
      if (aliveFrame(nn2) && nn2.name && nn2.name.indexOf("portfolio-section") !== -1) {
        portfolioSection = nn2; break;
      }
    }
    if (portfolioSection) {
      var newCardW = 220, newCardH = 320, newPhotoH = 200, newGap = 65;
      var teamCards = [];
      for (var ci = 0; ci < portfolioSection.children.length; ci++) {
        var c = portfolioSection.children[ci];
        if (c.type === "FRAME" && c.name && c.name.indexOf("card") !== -1) teamCards.push(c);
      }
      teamCards.sort(function (a, b) { return a.x - b.x; });
      for (var tc = 0; tc < teamCards.length; tc++) {
        var card2 = teamCards[tc];
        if (!isAlive(card2)) continue;
        try {
          if (Math.abs(card2.height - newCardH) < 5) continue; // idempotent
          card2.x = tc * (newCardW + newGap);
          card2.y = 0;
          card2.resize(newCardW, newCardH);
          try { card2.cornerRadius = 6; } catch (e) {}
          card2.fills = [{ type: "SOLID", color: COLORS.bgCard }];
          card2.strokes = [{ type: "SOLID", color: COLORS.borderLight }];
          card2.strokeWeight = 1;
          // Avatar / image container
          var avatar = card2.findOne(function (x) {
            return x.type === "FRAME" && x.name && (x.name.indexOf("avatar") !== -1 || x.name.indexOf("img") !== -1);
          });
          if (avatar) {
            avatar.x = 0; avatar.y = 0;
            try { avatar.resize(newCardW, newPhotoH); } catch (e) {}
            try { avatar.cornerRadius = 0; } catch (e) {}
            // Imagen interna
            for (var ai = 0; ai < avatar.children.length; ai++) {
              var inner = avatar.children[ai];
              if (inner.type === "RECTANGLE" || inner.type === "ROUNDED_RECTANGLE") {
                try { inner.x = 0; inner.y = 0; } catch (e) {}
                try { inner.resize(newCardW, newPhotoH); } catch (e) {}
                try { inner.cornerRadius = 0; } catch (e) {}
              }
            }
          }
          // Textos
          var allCardTexts = card2.findAll(function (x) { return x.type === "TEXT" && isAlive(x); });
          var h3node = null, roleNode = null;
          for (var ti = 0; ti < allCardTexts.length; ti++) {
            var ttn = allCardTexts[ti];
            if (ttn.name === "<h3>") h3node = ttn;
            else if (ttn.name === "role") roleNode = ttn;
          }
          if (!h3node && allCardTexts.length > 0) h3node = allCardTexts[0];
          if (!roleNode && allCardTexts.length > 1) {
            for (var rj = 0; rj < allCardTexts.length; rj++) {
              if (allCardTexts[rj] !== h3node) { roleNode = allCardTexts[rj]; break; }
            }
          }
          if (h3node) {
            h3node.x = 0; h3node.y = 216;
            try { h3node.textAlignHorizontal = "CENTER"; h3node.resize(newCardW, h3node.height); } catch (e) {}
          }
          if (roleNode) {
            roleNode.x = 0; roleNode.y = 244;
            try { roleNode.textAlignHorizontal = "CENTER"; roleNode.resize(newCardW, roleNode.height); } catch (e) {}
          }
          // Botón
          var btn = card2.findOne(function (x) {
            return x.type === "FRAME" && x.name && x.name.indexOf("btn") !== -1;
          });
          if (btn) {
            btn.x = Math.round((newCardW - btn.width) / 2);
            btn.y = 272;
          }
          stats.teamCardsRestructured++;
        } catch (e) { stats.errors.push("teamcard: " + e.message); }
      }
      try {
        portfolioSection.resize(teamCards.length * (newCardW + newGap) - newGap, newCardH);
      } catch (e) {}
    }
    log("   ✓ " + stats.teamCardsRestructured + " team cards restructuradas");

    // ════════════════════════════════════════════════════════════════════════
    // STEP 9 · Service cards 2×2 + íconos SVG
    // ════════════════════════════════════════════════════════════════════════
    log("");
    log("9) Service cards 2×2 + íconos SVG…");
    var SVG_ICONS = {
      "Card - Diseño UX/UI":         '<svg width="40" height="40" viewBox="0 0 40 40" xmlns="http://www.w3.org/2000/svg"><rect x="6" y="6" width="22" height="22" rx="2" stroke="#003366" stroke-width="2" fill="none"/><circle cx="14" cy="14" r="2" fill="#003366"/><path d="M22 22 L30 30 L26 30 Z" fill="#ff6600"/></svg>',
      "Card - Desarrollo Front-end": '<svg width="40" height="40" viewBox="0 0 40 40" xmlns="http://www.w3.org/2000/svg"><path d="M14 12 L7 20 L14 28" stroke="#003366" stroke-width="2.5" fill="none" stroke-linecap="round" stroke-linejoin="round"/><path d="M26 12 L33 20 L26 28" stroke="#003366" stroke-width="2.5" fill="none" stroke-linecap="round" stroke-linejoin="round"/><line x1="23" y1="10" x2="17" y2="30" stroke="#ff6600" stroke-width="2.5" stroke-linecap="round"/></svg>',
      "Card - User Research":        '<svg width="40" height="40" viewBox="0 0 40 40" xmlns="http://www.w3.org/2000/svg"><circle cx="17" cy="17" r="9" stroke="#003366" stroke-width="2.5" fill="none"/><line x1="24" y1="24" x2="32" y2="32" stroke="#ff6600" stroke-width="2.5" stroke-linecap="round"/><circle cx="17" cy="14" r="2.5" fill="#003366"/><path d="M11 22 Q11 19 14 19 L20 19 Q23 19 23 22" fill="#003366"/></svg>',
      "Card - Marketing Digital":    '<svg width="40" height="40" viewBox="0 0 40 40" xmlns="http://www.w3.org/2000/svg"><rect x="6" y="24" width="6" height="10" fill="#003366"/><rect x="16" y="18" width="6" height="16" fill="#003366"/><rect x="26" y="10" width="6" height="24" fill="#ff6600"/></svg>',
    };
    var servicesGrid = findFrameByName("Services Grid");
    if (servicesGrid) {
      var svcW = 640, svcH = 220, svcGap = 80, svcVGap = 24;
      var cardOrder = ["Card - Diseño UX/UI", "Card - Desarrollo Front-end", "Card - User Research", "Card - Marketing Digital"];
      for (var co = 0; co < cardOrder.length; co++) {
        var svcCard = findFrameByName(cardOrder[co]);
        if (!svcCard) continue;
        try {
          var col = co % 2, row = Math.floor(co / 2);
          svcCard.x = col * (svcW + svcGap);
          svcCard.y = row * (svcH + svcVGap);
          svcCard.resize(svcW, svcH);
          try { svcCard.cornerRadius = 6; } catch (e) {}
          svcCard.fills = [{ type: "SOLID", color: COLORS.bgCard }];
          svcCard.strokes = [{ type: "SOLID", color: COLORS.borderCard }];
          svcCard.strokeWeight = 1;
          // TopBorder
          var topB = svcCard.findOne(function (x) { return x.name === "TopBorder"; });
          if (topB) {
            try {
              topB.x = 0; topB.y = 0;
              topB.resize(svcW, 4);
              topB.fills = [{ type: "SOLID", color: COLORS.primary }];
            } catch (e) {}
          }
          // Icon area
          var iconArea = svcCard.findOne(function (x) { return x.name === "Icon Area"; });
          if (!iconArea) {
            iconArea = figma.createFrame();
            iconArea.name = "Icon Area";
            try { iconArea.cornerRadius = 8; } catch (e) {}
            svcCard.appendChild(iconArea);
          }
          iconArea.fills = [{ type: "SOLID", color: COLORS.bgIcon }];
          iconArea.x = 24;
          iconArea.y = Math.round((svcH - 80) / 2);
          iconArea.resize(80, 80);
          // Remover ícono existente y agregar nuevo
          var existingSvg = iconArea.findOne(function (x) { return x.name === "icon-svg"; });
          if (existingSvg) await safeRemove(existingSvg);
          try {
            var svgStr = SVG_ICONS[cardOrder[co]];
            if (svgStr) {
              var svgNode = figma.createNodeFromSvg(svgStr);
              svgNode.name = "icon-svg";
              svgNode.x = 20; svgNode.y = 20;
              iconArea.appendChild(svgNode);
              stats.iconsAdded++;
            }
          } catch (e) { stats.errors.push("svg: " + e.message); }
          // Reposicionar título y descripción
          var svcTexts = svcCard.findAll(function (x) { return x.type === "TEXT" && isAlive(x); });
          // Filtrar para no contar texts dentro del icon
          var realTexts = [];
          for (var rt = 0; rt < svcTexts.length; rt++) {
            var rtn = svcTexts[rt];
            // Saltear si está dentro de Icon Area
            var par = rtn.parent;
            var inIcon = false;
            while (par && par !== svcCard) {
              if (par.name === "Icon Area" || par.name === "icon-svg") { inIcon = true; break; }
              par = par.parent;
            }
            if (!inIcon) realTexts.push(rtn);
          }
          if (realTexts.length >= 2) {
            var sortedT = realTexts.slice().sort(function (a, b) { return a.characters.length - b.characters.length; });
            var titleN = sortedT[0], descN = sortedT[sortedT.length - 1];
            titleN.x = 124; titleN.y = 60;
            try { titleN.resize(480, titleN.height); } catch (e) {}
            descN.x = 124; descN.y = 95;
            try { descN.resize(480, descN.height); } catch (e) {}
          }
          stats.serviceCardsRestructured++;
        } catch (e) { stats.errors.push("svccard layout: " + e.message); }
      }
      try { servicesGrid.resize(2 * svcW + svcGap, 2 * svcH + svcVGap); } catch (e) {}
    }
    log("   ✓ " + stats.serviceCardsRestructured + " service cards en 2×2, " + stats.iconsAdded + " íconos");

    // ════════════════════════════════════════════════════════════════════════
    // STEP 10 · Style Guide: limpiar Box Model + paleta completa
    // ════════════════════════════════════════════════════════════════════════
    log("");
    log("10) Style Guide: limpieza + paleta completa…");
    var sg = findFrameByName("Nexo Studio – Style Guide") || findFrameByName("Style Guide");
    if (sg) {
      // 10a: borrar bloque Box Model
      var boxKeywords = ["BOX MODEL", "Cómo organizar 5 columnas", ".portfolio-section", ".card {", "display: inline-block", "Sin Auto Layout"];
      var toRemove = [];
      for (var ch = 0; ch < sg.children.length; ch++) {
        var child = sg.children[ch];
        try {
          if (child.type === "TEXT") {
            for (var bk = 0; bk < boxKeywords.length; bk++) {
              if (child.characters && child.characters.indexOf(boxKeywords[bk]) !== -1) {
                toRemove.push(child); break;
              }
            }
          }
          // Rectángulos grandes asociados al Box Model (y entre 700 y 800, ancho 860 o 440)
          if ((child.type === "RECTANGLE" || child.type === "ROUNDED_RECTANGLE") &&
              child.y > 700 && child.y < 800 &&
              (Math.abs(child.width - 860) < 5 || Math.abs(child.width - 440) < 5)) {
            toRemove.push(child);
          }
          // Línea separadora arriba del Box Model
          if (child.type === "LINE" && Math.abs(child.y - 698) < 5) toRemove.push(child);
        } catch (e) {}
      }
      for (var rm = 0; rm < toRemove.length; rm++) {
        await safeRemove(toRemove[rm]);
        stats.boxModelRemoved++;
      }
      if (stats.boxModelRemoved > 0) log("   ✓ Box Model: " + stats.boxModelRemoved + " nodos removidos");

      // 10b: agregar 11 colores faltantes
      var alreadyAdded = sg.findOne(function (x) { return x.name === "swatch-accent-hover"; });
      if (!alreadyAdded) {
        var missingColors = [
          { hex: "#cc5200", role: "Accent Hover",     varname: "--color-accent-hover" },
          { hex: "#f8f8f8", role: "BG Card/Footer",   varname: "--color-bg-card" },
          { hex: "#f0f4fa", role: "BG Ícono",         varname: "--color-bg-icon" },
          { hex: "#fff4ee", role: "BG Ícono Hover",   varname: "--color-bg-icon-hover" },
          { hex: "#002255", role: "Nav Mobile",       varname: "--color-nav-mobile" },
          { hex: "#444444", role: "Text Párrafo",     varname: "--color-text-para" },
          { hex: "#555555", role: "Text Secundario",  varname: "--color-text-secondary" },
          { hex: "#888888", role: "Text Muted",       varname: "--color-text-muted" },
          { hex: "#e8e8e8", role: "Borde Claro",      varname: "--color-border-light" },
          { hex: "#e0e0e0", role: "Borde Card",       varname: "--color-border-card" },
          { hex: "#cccccc", role: "Input Borde",      varname: "--color-input-border" },
        ];
        var startY = 720, rowH = 130, colW = 200, colGap = 24, stride = colW + colGap, startX = 40;
        for (var mc = 0; mc < missingColors.length; mc++) {
          var cc = missingColors[mc];
          var col2 = mc % 4, row2 = Math.floor(mc / 4);
          var xx = startX + col2 * stride;
          var yy = startY + row2 * rowH;
          var hex = cc.hex.replace("#", "");
          var rR = parseInt(hex.substr(0, 2), 16);
          var rG = parseInt(hex.substr(2, 2), 16);
          var rB = parseInt(hex.substr(4, 2), 16);
          try {
            var swRect = figma.createRectangle();
            swRect.name = "swatch-" + cc.role.toLowerCase().replace(/[^a-z0-9]+/g, "-");
            swRect.resize(colW, 80);
            swRect.x = xx; swRect.y = yy;
            try { swRect.cornerRadius = 8; } catch (e) {}
            swRect.fills = [{ type: "SOLID", color: rgb(rR, rG, rB) }];
            swRect.strokes = [{ type: "SOLID", color: COLORS.borderLight }];
            swRect.strokeWeight = 1;
            sg.appendChild(swRect);

            var l1 = figma.createText();
            try { l1.fontName = { family: "Montserrat", style: "SemiBold" }; } catch (e) {}
            l1.characters = cc.role;
            l1.fontSize = 13;
            l1.fills = [{ type: "SOLID", color: COLORS.textMain }];
            l1.x = xx; l1.y = yy + 88;
            sg.appendChild(l1);

            var l2 = figma.createText();
            try { l2.fontName = { family: "Montserrat", style: "Regular" }; } catch (e) {}
            l2.characters = cc.hex.toUpperCase();
            l2.fontSize = 12;
            l2.fills = [{ type: "SOLID", color: COLORS.textPara }];
            l2.x = xx; l2.y = yy + 104;
            sg.appendChild(l2);

            var l3 = figma.createText();
            try { l3.fontName = { family: "Open Sans", style: "Regular" }; } catch (e) {}
            l3.characters = cc.varname;
            l3.fontSize = 11;
            l3.fills = [{ type: "SOLID", color: COLORS.textMuted }];
            l3.x = xx; l3.y = yy + 120;
            sg.appendChild(l3);

            stats.swatchesAdded++;
          } catch (e) { stats.errors.push("swatch: " + e.message); }
        }
        // Resize SG si hace falta
        try {
          var needH = startY + Math.ceil(missingColors.length / 4) * rowH + 80;
          if (sg.height < needH) sg.resize(sg.width, needH);
        } catch (e) {}
      }
      log("   ✓ " + stats.swatchesAdded + " swatches nuevos");
    }

    // ════════════════════════════════════════════════════════════════════════
    // STEP 11 · Nav uppercase + underline activo
    // ════════════════════════════════════════════════════════════════════════
    log("");
    log("11) Nav uppercase + underline activo…");
    var pageMap = {
      "Nexo Studio – Inicio":    "INICIO",
      "Nexo Studio – Servicios": "SERVICIOS",
      "Nexo Studio – Proyectos": "PROYECTOS",
      "Nexo Studio – Contacto":  "CONTACTO",
    };
    for (var pp = 0; pp < allNodes.length; pp++) {
      var pageFrame = allNodes[pp];
      if (!aliveFrame(pageFrame) || !pageMap[pageFrame.name]) continue;
      var activeLabel = pageMap[pageFrame.name];
      var nav = pageFrame.findOne(function (x) { return x.type === "FRAME" && x.name === "Nav"; });
      if (!nav) continue;
      var navTexts = nav.findAll(function (x) { return x.type === "TEXT" && isAlive(x); });
      for (var nt = 0; nt < navTexts.length; nt++) {
        var navText = navTexts[nt];
        try {
          var upper = navText.characters.toUpperCase();
          if (navText.characters !== upper) {
            await setText(navText, upper);
            stats.navsUpdated++;
          }
          if (upper === activeLabel) {
            var existsU = nav.findOne(function (x) { return x.name === "active-underline-" + activeLabel; });
            if (!existsU) {
              var underline = figma.createRectangle();
              underline.name = "active-underline-" + activeLabel;
              underline.resize(Math.max(20, navText.width), 2);
              underline.x = navText.x;
              underline.y = navText.y + navText.height + 4;
              underline.fills = [{ type: "SOLID", color: COLORS.accent }];
              nav.appendChild(underline);
            }
          }
        } catch (e) { stats.errors.push("nav: " + e.message); }
      }
    }
    log("   ✓ " + stats.navsUpdated + " textos uppercased + underline activo");

    // ════════════════════════════════════════════════════════════════════════
    // RESUMEN
    // ════════════════════════════════════════════════════════════════════════
    log("");
    log("════════════════════════════════════════");
    log("Resumen Nexo Studio v3:");
    log("   • Frames renombrados:        " + stats.framesRenamed);
    log("   • Textos reemplazados:       " + stats.textsReplaced);
    log("   • Service cards actualizadas: " + stats.serviceCardsUpdated);
    log("   • Service cards eliminadas:  " + stats.serviceCardsDeleted);
    log("   • Bordes naranja aplicados:  " + stats.bordersApplied);
    log("   • Imágenes insertadas:       " + stats.imagesInserted);
    log("   • Team cards restructuradas: " + stats.teamCardsRestructured);
    log("   • Service cards 2×2:         " + stats.serviceCardsRestructured);
    log("   • Íconos SVG agregados:      " + stats.iconsAdded);
    log("   • Swatches paleta:           " + stats.swatchesAdded);
    log("   • Box Model nodos removed:   " + stats.boxModelRemoved);
    log("   • Nav texts uppercased:      " + stats.navsUpdated);
    log("   • Errores:                   " + stats.errors.length);
    if (stats.errors.length > 0) {
      log("");
      log("Errores detectados:");
      for (var ei = 0; ei < stats.errors.length; ei++) log("   - " + stats.errors[ei]);
    }
    log("════════════════════════════════════════");

    var total = stats.framesRenamed + stats.textsReplaced + stats.serviceCardsUpdated +
                stats.serviceCardsDeleted + stats.bordersApplied + stats.imagesInserted +
                stats.teamCardsRestructured + stats.serviceCardsRestructured +
                stats.iconsAdded + stats.swatchesAdded + stats.boxModelRemoved + stats.navsUpdated;
    if (stats.errors.length > 0) {
      figma.notify("✓ " + total + " cambios. " + stats.errors.length + " errores — revisá consola.", { timeout: 10000 });
    } else if (total === 0) {
      figma.notify("Nada para cambiar — el archivo ya está completo", { timeout: 6000 });
    } else {
      figma.notify("✓ Nexo Studio v3: " + total + " cambios aplicados", { timeout: 8000 });
    }
  } catch (err) {
    console.error("[NEXO] Fatal:", err);
    figma.notify("Error fatal: " + err.message, { error: true, timeout: 12000 });
  } finally {
    figma.closePlugin();
  }
})();
